def generate(seed):
    r = random.Random(seed)
    for _ in range(150):
        W = r.randint(30, 40)
        D = r.randint(5, 6)
        cols, x = [], r.randint(2, 4)
        while x <= W - 3:                          # weeds, 5-9 columns apart
            cols.append(x)
            x += r.randint(5, 9)
        if not 4 <= len(cols) <= 6:
            continue
        hs = [min(r.choice((2, 3, 3, 4)), D - 1) for _ in cols]
        k = r.randrange(len(cols))
        hs[k] = D - 1                              # one weed right up to the water top
        hs[k - 1] = 2                              # and one little one
        g, top = [["."] * W for _ in range(D)], {}
        for c, h in zip(cols, hs):
            top[c] = D - h                         # the row the weed's tip is in
            for i in range(D - h, D):
                g[i][c] = "|"

        def free(i, a, d):
            if a < 0 or a + 3 > W:
                return False
            if any(g[i][x] != "." for x in range(a, a + 3)):
                return False
            for x in (a - 1, a + 3):               # never draw two fish touching
                if 0 <= x < W and g[i][x] in "<>":
                    return False
            no = a + 3 if d > 0 else a - 1         # a clue fish never starts nose-on-weed
            return not (0 <= no < W and g[i][no] != ".")

        def look(i, a, e):
            """the first thing that is not open water, e-wards of the fish at a"""
            j = a + 3 if e > 0 else a - 1
            while 0 <= j < W and g[i][j] == ".":
                j += e
            return (g[i][j], j) if 0 <= j < W else ("#", -1)

        def thru(i, a, d):
            """a weed somewhere ahead, even past the other fish"""
            j = a + 3 if d > 0 else a - 1
            while 0 <= j < W and g[i][j] != "|":
                j += d
            return 0 <= j < W

        def okay(i, a, d):
            """legal, and nobody is left staring at a weed through another fish"""
            if per[i] > 2 or not free(i, a, d):
                return False
            if not thru(i, a, d):
                return True
            return look(i, a, d)[0] not in "<>" and look(i, a, -d)[0] != (">" if d > 0 else "<")

        def put(i, a, d):
            g[i][a:a + 3] = list("><>" if d > 0 else "<><")
            per[i] += 1

        # ---- every fish that is looking straight at a weed ------------------
        near, far = [], []
        for c, h in zip(cols, hs):
            for i in range(D - h, D):
                for gap in (2, 3, 4, 5, 6):
                    for d in (1, -1):
                        a = c - 3 - gap if d > 0 else c + 1 + gap
                        if free(i, a, d) and look(i, a, d) == ("|", c):
                            q = (i, a, d, c, h, i - top[c], gap)
                            (near if q[5] < 2 else far).append(q)
        r.shuffle(near)
        r.shuffle(far)
        per = [0] * D

        # ---- the nibblers, chosen so that the near misses have teeth --------
        want = 0 if r.random() < 0.115 else r.choice((1, 2, 2, 3))
        wish = []
        if r.random() < 0.9:
            wish.append(lambda q: q[5] == 1)       # one bite a row above the fish
        if r.random() < 0.9:
            wish.append(lambda q: q[4] > 2)        # one on a big weed (high up)
        if r.random() < 0.85:
            wish.append(lambda q: q[0] == D - 1)   # one right down on the gravel
        r.shuffle(wish)
        nib, weeds_used = [], set()

        keep = r.random() < 0.85                   # the big weed is left for the fish
        def hire(q):                               # who cannot reach its top
            (i, a, d, c, h, o, gap) = q
            if c in weeds_used or (keep and h == D - 1) or not okay(i, a, d):
                return False
            put(i, a, d)
            for x in (range(a + 3, c) if d > 0 else range(c + 1, a)):
                g[i][x] = ":"                      # reserve the swim corridor
            nib.append(q)
            weeds_used.add(c)
            return True

        for w in wish[:want]:
            for q in near:
                if len(nib) == want:
                    break
                if w(q) and hire(q):
                    break
        for q in near:
            if len(nib) == want:
                break
            hire(q)
        if bool(nib) != bool(want):
            continue

        # ---- fish that cannot reach the top of the weed they are facing -----
        wf, nf = r.choice((3, 3, 4)), 0
        goals = []
        if nib:
            deep = max(q[0] for q in nib)
            lo = min(q[6] for q in nib)
            hi = max(q[6] for q in nib)
            goals = [lambda q: q[0] < deep,        # one of them higher than a nibbler
                     lambda q: q[6] > lo,          # one of them further from its weed
                     lambda q: q[6] < hi]          # one of them nearer to its weed

        def enlist(q):
            (i, a, d, c, h, o, gap) = q
            if c in weeds_used or not okay(i, a, d):
                return False
            put(i, a, d)
            return True

        for gl in goals:
            for q in far:
                if nf == wf:
                    break
                if gl(q) and enlist(q):
                    nf += 1
                    break
        for q in far:
            if nf == wf:
                break
            if enlist(q):
                nf += 1
        if not nf:
            continue

        # ---- a weed behind their tail, or nowhere near a weed ---------------
        spots = [(i, a, d) for i in range(D) for a in range(W - 2) for d in (1, -1)]
        r.shuffle(spots)
        na, no = 0, 0
        wa, wo = r.choice((1, 2)), r.random() < 0.6
        for (i, a, d) in spots:
            if na >= wa and no >= wo:
                break
            if look(i, a, d)[0] == "|" or not okay(i, a, d):
                continue
            if na < wa and look(i, a, -d)[0] == "|":
                put(i, a, d)                       # a weed behind its tail
                na += 1
            elif no < wo and not thru(i, a, d):
                put(i, a, d)                       # nowhere near a weed
                no += 1
        if na < 1:
            continue

        rows = ["".join(x).replace(":", ".") for x in g]
        n = 0
        for i, row in enumerate(rows):
            for m in re.finditer("><>|<><", row):
                a = m.start()
                d = 1 if row[a] == ">" else -1
                j = a + 3 if d > 0 else a - 1
                while 0 <= j < W and row[j] == ".":
                    j += d
                if 0 <= j < W and row[j] == "|":
                    n += i - top[j] < 2
                elif 0 <= j < W and row[j] in "<>":
                    n = -99                        # nobody may be stuck behind a fish
        if n != len(nib):
            continue
        return "\n".join(["~" * W] + rows + ["#" * W, "%d nibble" % n])
    return FB

